const invoices = $input.all().map(i => i.json);
const total = invoices.reduce((sum, inv) => sum + (Number(inv.total) || 0), 0);
const byCustomer = {};
for (const inv of invoices) {
  const name = inv.contactName || inv.contact || 'Unknown';
  byCustomer[name] = (byCustomer[name] || 0) + (Number(inv.total) || 0);
}
const top = Object.entries(byCustomer).sort((a, b) => b[1] - a[1])[0];
const date = $now.minus({ days: 1 }).toFormat('dd/MM/yyyy');
const lines = [
  `:page_facing_up: *Holded sales report — ${date}*`,
  `• Invoices issued: *${invoices.length}*`,
  `• Total billed: *${total.toFixed(2)} €*`,
];
if (top) lines.push(`• Top customer: *${top[0]}* (${top[1].toFixed(2)} €)`);
if (!invoices.length) lines.push('_No invoices yesterday._');
return [{ json: { report: lines.join('\n') } }];
